        if (!f) return { lines: [], meta: {}, missing: true };
        const rows = [];
        for (const line of String(f.text).split(/\r?\n/)) {
          if (!line.trim()) continue;
          try {
            rows.push(JSON.parse(line));
          } catch {}
        }
