        const start = rows.find((r) => r.type === "session-start") || {};
        const end = rows.find((r) => r.type === "session-end") || {};
        // Speaker photos the controller cropped out of the call, so the
        // dashboard shows the same faces the Teams captions panel did.
        const stem = entry.fileName.replace(/\.html$/, "");
        const assets = `${entry.root}/${entry.year}/${entry.month}/${stem}-speakers`;
        const screensDir = `${entry.root}/${entry.year}/${entry.month}/${stem}-screens`;
        const photos = {};
        await Promise.all(
          rows
            .filter((r) => r.type === "speaker-photo" && r.speaker && r.file)
            .map(async (r) => {
              const url = await ghGetImage(`${assets}/${r.file}`).catch(() => null);
              if (url) photos[r.speaker] = url;
            }),
        );
