          label: "Docs manifests (GitHub)",
          path: "Work|Personal/{Glossary,Processes,Decisions}/docs.json",
          coverage: docsCoverage,
          message:
            docsCoverage.malformed || docsCoverage.missing || docsCoverage.unreachable
