  async function loadJson(path, meta = {}) {
    const source = meta.source || dataHealthSourceKey("json.load", path);
    const label = meta.label || dataHealthLabelFromPath(path);
    try {
      const t = await readPath(path);
      if (!t) {
        setDataHealth(source, {
          source,
          label,
          path,
          status: "missing",
          message: `${label} not found at ${path}.`,
          coverage: { expected: 1, missing: 1 },
        });
        return null;
      }
      const parsed = DataHealth.parseJsonDocument(
        t,
        {
          source,
          label,
          path,
          message: `${label} is malformed at ${path}.`,
        },
        Date.now(),
      );
      if (!parsed.ok) {
        addDataHealthIssue(parsed.issue);
        return null;
      }
      setDataHealth(source, {
        source,
        label,
        path,
        status: "ok",
        message: `${label} loaded.`,
        coverage: { expected: 1, found: 1, ok: 1 },
      });
      return parsed.value;
    } catch (error) {
      setDataHealth(source, {
        source,
        label,
        path,
        status: "unreachable",
        message: `${label} could not be read from ${path}.`,
        detail: error?.message || "",
        coverage: { expected: 1, unreachable: 1 },
      });
      return null;
    }
  }
