  function dedupeByLatest(list, keyFn, tsFn) {
    const map = new Map();
    for (const item of list) {
      const key = keyFn(item);
      const prev = map.get(key);
      if (!prev || tsFn(item) >= tsFn(prev)) map.set(key, item);
    }
    return [...map.values()];
  }
  // Live sessions from the database (#26). The rows have been current to the
  // minute for a week; the git files duplicate them. Field names differ between
  // the two shapes, so the mapping is explicit rather than a spread -- a silent
  // rename here would empty the sessions strip with no error anywhere.
  async function loadSessionsFromSupabase() {
    if (!window.WBSupabaseAuth?.hasSession?.()) return null;
    try {
      const rows = await ensureSupabaseDataClient().select("sessions", {
        columns:
          "session_uid,session_short,session_full,machine_id,cwd,ide,editor,backend,model," +
          "status,live_state,latest_prompt,started_at,updated_at,todo_counts,active_todo",
        order: "updated_at.desc",
        limit: 400,
      });
      if (!Array.isArray(rows) || !rows.length) return null;
      return rows.map((row) => ({
        machine: row.machine_id,
        session_uid: row.session_uid,
        session: row.session_short || String(row.session_uid || "").slice(0, 8),
        sessionFull: row.session_full || row.session_uid,
        session_full: row.session_full,
        machine_id: row.machine_id,
        nativeIdentity: row.session_uid && row.session_full && row.machine_id && row.ide && row.editor
          ? { sessionUid: row.session_uid, nativeSessionId: row.session_full, machineId: row.machine_id, ide: row.ide, editor: row.editor }
          : null,
        cwd: row.cwd,
        ide: row.ide,
        editor: row.editor,
        backend: row.backend,
        model: row.model,
        // `live_state` is the richer of the two and what the strip reads for
        // activity; `status` is the coarse rollup.
        status: row.live_state || row.status,
        prompt: row.latest_prompt,
        started: Date.parse(row.started_at) || 0,
        updated: Date.parse(row.updated_at) || 0,
        todoCounts: row.todo_counts,
        activeTodo: row.active_todo,
        _path: `supabase:sessions/${row.session_uid}`,
      }));
    } catch {
      return null;
    }
  }

  // Tower Previews, web-shell slice (plan at
