  // Sync status lives on the machines row as `sync_status` jsonb, written by
  // workbench_io.write_sync_status. Reading it from there is what lets
  // Tools/sync-status/ stop being committed (#26) -- this was the last surface
  // still git-only, and cutting the files without this would simply have
  // blanked it.
  async function loadSyncStatusFromSupabase() {
    if (!window.WBSupabaseAuth?.hasSession?.()) return null;
    try {
      const rows = await ensureSupabaseDataClient().select("machines", {
        columns: "machine_id,sync_status,status",
        order: "updated_at.desc",
      });
      if (!Array.isArray(rows)) return null;
      const out = rows
        .filter((row) => row?.sync_status && !row?.status?.producerOnly)
        .map((row) => ({
          ...row.sync_status,
          machine: row.sync_status.machine || row.machine_id,
          _path: `supabase:machines/${row.machine_id}#sync_status`,
        }));
      // No rows is not the same as no database. Returning [] here would report
      // a healthy empty surface; returning null falls through to git.
      return out.length ? out : null;
    } catch {
      return null;
    }
  }

