  // Checkout ledger: per-machine derived indexes written by
  // Tools/checkout-ledger.py. Two small files instead of enumerating
  // Tools/checkouts/events/ (one GitHub API fetch per file on the phone).
  async function loadCheckouts() {
    const indexes = [];
    const coverage = {
      expected: 0,
      found: 0,
      ok: 0,
      missing: 0,
      malformed: 0,
      unreachable: 0,
    };

    const tree = await ghGetTree().catch(() => {
      coverage.unreachable += 1;
      return [];
    });
    await batch(
      tree.filter((p) => /^Tools\/checkouts\/index-[^/]+\.json$/.test(p)),
      async (p) => {
        coverage.expected += 1;
        let f;
        try {
          f = await ghGetFile(p);
          coverage.found += 1;
        } catch (error) {
          coverage.unreachable += 1;
          addDataHealthIssue(
            DataHealth.buildSourceHealth(
              {
                source: dataHealthSourceKey("hydrate.checkouts.unreachable", p),
                label: `Checkout index · ${p.split("/").pop()?.replace(/\.json$/, "")}`,
                path: p,
                status: "unreachable",
                message: `Could not read checkout index at ${p}.`,
                detail: error?.message || "",
                coverage: { expected: 1, unreachable: 1 },
              },
              Date.now(),
            ),
          );
          return;
        }
        const parsed = readJsonDocument(f?.text, {
          source: dataHealthSourceKey("hydrate.checkouts.malformed", p),
          label: `Checkout index · ${p.split("/").pop()?.replace(/\.json$/, "")}`,
          path: p,
          message: `Malformed checkout index at ${p}; skipping file.`,
        });
        if (!parsed.ok) {
          coverage.malformed += 1;
          return;
        }
        coverage.ok += 1;
        indexes.push(parsed.value);
      },
    );

    // merge per scope, freshest machine's view wins
    const scopes = {};
    for (const idx of indexes)
      for (const [scope, st] of Object.entries(idx.scopes || {})) {
        const prev = scopes[scope];
        if (!prev || (st.lastEventTs || 0) >= (prev.lastEventTs || 0))
          scopes[scope] = st;
      }
    setDataHealth("hydrate.checkouts", {
      label: "Checkout indexes",
      path: "Tools/checkouts/index-*.json",
      coverage,
      status: coverage.unreachable
        ? "unreachable"
        : coverage.malformed
          ? "malformed"
          : coverage.expected && !coverage.found
            ? "missing"
            : "ok",
      message: coverage.malformed
        ? `${coverage.malformed} malformed checkout index file(s) skipped.`
        : `Loaded ${indexes.length} checkout index file(s).`,
      updatedMs: Object.values(scopes).reduce(
        (m, st) => Math.max(m, Number(st.lastEventTs || 0)),
        0,
      ) || null,
      staleAfterMs: 2 * 60 * 60 * 1000,
    });
    return scopes;
  }
  function claimIsLive(st) {
    if (!st || st.state !== "checked-out" || !st.owner) return false;
    if ((st.expiresAt || 0) <= Date.now()) return false;
    // live only when the owning session's beacon is present and fresh
    const beacon = (state.sessions || []).find(
      (s) =>
        sessionMachine(s) === st.owner.machine &&
        (s.session || "") === st.owner.session,
    );
    return !!beacon && !isStaleSession(beacon) && beacon.status !== "ended";
  }
  function checkoutForProject(p) {
    const scopes = state.checkouts || {};
    return scopes[`${p.section}/Projects/${p.dirName}/**`] || null;
  }
  function checkoutChipHTML(p) {
    const st = checkoutForProject(p);
    if (!st || st.state !== "checked-out" || !st.owner) return "";
    const who = `${st.owner.ide || "agent"} @ ${machineName(st.owner.machine)}`;
    if (claimIsLive(st))
      return `<span class="chip warn" title="Checked out by ${esc(who)} — coordinate before editing">🔒 ${esc(who)}</span>`;
    return `<span class="chip" title="Stale checkout by ${esc(who)} — takeover allowed">stale lock · ${esc(who)}</span>`;
  }
  async function pingHelper() {
    try {
      const r = await fetch(HELPER + "/ping", {
        headers: { "X-Workbench": "1" },
      });
      state.helperUp = r.ok;
      const s = await fetch(HELPER + "/status", {
        headers: { "X-Workbench": "1" },
      });
      state.helperStatus = s.ok ? await s.json() : null;
    } catch {
      state.helperUp = false;
      state.helperStatus = null;
    }
    renderStatusRail();
  }
  async function helperPost(ep) {
    const r = await fetch(HELPER + ep, {
      method: "POST",
      headers: { "X-Workbench": "1" },
    });
    const j = await r
      .json()
      .catch(() => ({ ok: false, message: "No response" }));
    if (!r.ok || !j.ok) throw new Error(j.message || "Helper failed");
    return j;
  }
  function counts(p) {
    const c = {
      all: 0,
      total: 0,
      open: 0,
      todo: 0,
      doing: 0,
      blocked: 0,
      idea: 0,
      done: 0,
    };
    for (const g of p.data.groups || [])
      for (const it of g.items || []) {
        c.all++;
        if (it.status === "done") {
          c.done++;
          c.total++;
        } else if (it.status === "idea") c.idea++;
        else if (it.status === "skipped" || it.status === "cancelled") {
          c.done++;
          c.total++;
        } else {
          c.open++;
          c.total++;
          c[it.status] = (c[it.status] || 0) + 1;
        }
      }
    c.archivedDone = Number(p.data.archivedDone || 0);
    c.doneWithArchive = c.done + c.archivedDone;
    c.totalWithArchive = c.total + c.archivedDone;
    c.pct = c.totalWithArchive ? Math.round((c.doneWithArchive / c.totalWithArchive) * 100) : null;
    return c;
  }
  function globalStats() {
    const s = { open: 0, doing: 0, blocked: 0, done: 0, idea: 0, week: 0 };
    for (const p of state.projects) {
      const c = counts(p);
      s.open += c.open;
      s.doing += c.doing;
      s.blocked += c.blocked;
      s.done += c.doneWithArchive;
      s.idea += c.idea;
      for (const g of p.data.groups || [])
        for (const it of g.items || [])
          if (it.status === "done" && it.completed >= daysAgoISO(7)) s.week++;
    }
    return s;
  }
  function projectRecency(p) {
    let max = 0;
    for (const l of p.log || []) {
      const t = Date.parse(l.ts.replace(" ", "T"));
      if (t > max) max = t;
    }
    for (const g of p.data.groups || [])
      for (const it of g.items || [])
        for (const d of [it.created, it.completed]) {
          const t = Date.parse(d || "");
          if (t > max) max = t;
        }
    return max;
  }
  function progress(c) {
    return `<span class="progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${c.pct ?? 0}" aria-label="Progress ${c.pct ?? 0}%"><i style="width:${c.pct ?? 0}%"></i></span>`;
  }
  function isClosedStatus(status) {
    return status === "done" || status === "skipped" || status === "cancelled";
  }
  function label(status, text = status) {
    const cls =
      status === "blocked"
        ? "bad"
        : isClosedStatus(status)
          ? "ok"
          : status === "doing"
            ? "ok"
            : status === "idea"
              ? "warn"
              : "";
    return `<span class="chip ${cls}">${esc(text)}</span>`;
  }
  function displayText(t, n = 150) {
    t = String(t || "")
      .replace(/\s+/g, " ")
      .replace(/[`*_#]/g, "")
      .trim();
    return t.length > n ? t.slice(0, n).replace(/\s+\S*$/, "") + "…" : t;
  }
  function priorityWeight(v) {
    v = String(v || "").toLowerCase();
    if (/^(p0|urgent|critical|highest|now)$/.test(v)) return 4;
    if (/^(p1|high)$/.test(v)) return 3;
    if (/^(p2|medium|med)$/.test(v)) return 2;
    if (/^(p3|low|later)$/.test(v)) return 1;
    return 0;
  }
  function priorityLabel(v) {
    const w = priorityWeight(v);
    return w === 4 ? "P0" : w === 3 ? "P1" : w === 2 ? "P2" : w === 1 ? "P3" : "Unprioritized";
  }
  function projectPriority(p) {
    return p?.data?.priority || p?.data?.metadata?.priority || p?.data?.whatsNext?.priority || "";
  }
  function projectTargetDate(p) {
    return p?.data?.targetDate || p?.data?.metadata?.targetDate || p?.data?.whatsNext?.targetDate || "";
  }
  function taskPriority(a) {
    return a?.it?.priority || a?.wn?.priority || projectPriority(a?.p) || "";
  }
  function taskDue(a) {
    return a?.it?.due || a?.it?.targetDate || a?.wn?.due || a?.wn?.targetDate || projectTargetDate(a?.p) || "";
  }
  function dueTime(v) {
    const t = Date.parse(v || "");
    return isFinite(t) ? t : Infinity;
  }
  function dueLabel(v) {
    if (!v) return "No date";
    const t = dueTime(v);
    if (!isFinite(t)) return v;
    const d = Math.ceil((t - Date.now()) / 86400000);
    if (d < 0) return `${Math.abs(d)}d overdue`;
    if (d === 0) return "due today";
    if (d === 1) return "due tomorrow";
    return `${d}d out`;
  }
  function actionMode(a) {
    const h = (a.text + " " + (a.g?.name || "") + " " + (a.it?.mode || "")).toLowerCase();
    if (a.kind === "blocked" || /waiting|blocked|jared|confirm|decide|real device|phone/.test(h)) return "waiting";
    if (/verify|test|publish|screenshot|smoke|check/.test(h)) return "verify";
    if (/delegate|agent|bulk|mechanical|update skill/.test(h)) return "delegate";
    if (/idea|later|someday/.test(h) || a.kind === "idea") return "later";
    return a.kind === "doing" || a.kind === "wnext" ? "now" : "next";
  }
  function actionWhy(a) {
    if (a.kind === "blocked") return "Blocked work should be cleared before more buildout.";
    if (a.kind === "wnext") return a.wn?.why || "Recorded as the project handoff.";
    if (a.kind === "doing") return "Already in flight; finishing avoids context decay.";
    if (taskDue(a)) return `Date signal: ${dueLabel(taskDue(a))}.`;
    if (priorityWeight(taskPriority(a))) return `Priority signal: ${priorityLabel(taskPriority(a))}.`;
    return "First actionable item from the project queue.";
  }
  function projectCostSummary(p) {
    const allRows = uniqueSessionRows((state.sessionMetrics?.sessions || []).filter(Boolean));
    const allocator = WorkbenchProjectUsage.createAllocator(state.projects);
    const entries = usageRows(allRows).map((row) => ({ row,
      fraction: allocator.forProject(row, p),
    })).filter((entry) => entry.fraction > 0);
    const rows = entries.map((entry) => entry.row);
    const shares = planShareMap(rows, allRows);
    const triple = WorkbenchProjectUsage.sum(entries, (row) => ({
      billed: billedCost(row), planShare: shares.get(row) || 0,
      saved: savedCost(row), notional: notionalCost(row),
    }), cacheInclusiveTokens);
    const unpriced = rows.filter((row) => sessionCost(row) == null).length;
    return {
      ...triple, rows, fractions: new Map(entries.map(({ row, fraction }) => [row, fraction])),
      // A project allocation is not an invoice. Preserve unavailable pricing
      // instead of turning an unpriced provider/model into a zero-dollar total.
      cost: unpriced ? null : triple.cost,
      knownCost: triple.cost,
      unpriced,
      allocationNote: WorkbenchProjectUsage.note + (unpriced
        ? ` ${unpriced} session records have unavailable pricing; known subtotal ${fmtCostMaybe(triple.cost)}.` : ""),
      tokens: triple.tokens,
      sessions: new Set(rows.map(workEpisodeIdentity)).size,
    };
  }

  function projectRelatedKB(p) {
    const key = String(p.data.project || p.dirName || "").toLowerCase();
    return (state.kb || []).filter((e) => `${e.title} ${e.summary} ${e.body}`.toLowerCase().includes(key)).slice(0, 5);
  }

