    if (month !== key) return observed;
    const daysInMonth = new Date(at.getFullYear(), at.getMonth() + 1, 0).getDate();
    const elapsed = Math.min(daysInMonth, Math.max(0.5, at.getDate() - 1 + at.getHours() / 24));
    const remainingFraction = Math.max(0, (daysInMonth - elapsed) / daysInMonth);
    const history = Object.entries(priorMonths)
      .filter(([m, v]) => m !== month && v > 0)
      .map(([, v]) => v)
      .sort((a, b) => a - b);
