    if (heavy) {
      const ccrTokens = ccrTokensOf(heavy);
      tips.push([
        "CCR concentrated",
        `${heavy.cwd.split("/").pop()} has ${fmtTokens(ccrTokens)} CCR tokens across GPT-5.5, Codex, Sol, Terra, or Luna. Consider scheduling heavy work around Anthropic quota resets when possible.`,
      ]);
    }
